<script lang="ts">
import{page}from"$app/state";import{goto}from"$app/navigation";import{tick}from"svelte";import{movies}from"../../../shared/catalog";
type Sort="relevance"|"title"|"year";let query=$state("");let status=$state("all");let sort=$state<Sort>("relevance");let filter:HTMLDialogElement;let ratingDialog:HTMLDialogElement;let rating=$state<number|null>(null);let started=0;let latency=$state("—");
let view=$derived(page.url.searchParams.get("vista")??"descubrir");let movieId=$derived(page.url.searchParams.get("pelicula"));let selected=$derived(movies.find(m=>m.id===movieId));
let results=$derived.by(()=>{const term=query.trim().toLocaleLowerCase("es");const current=status==="all"?(page.url.searchParams.get("estado")==="pendientes"?"Pendiente":page.url.searchParams.get("estado")==="historial"?"Vista":"all"):status;const list=movies.filter(m=>(!term||m.title.toLocaleLowerCase("es").includes(term)||m.genre.toLocaleLowerCase("es").includes(term)||String(m.year).includes(term))&&(current==="all"||m.status===current));if(sort==="title")list.sort((a,b)=>a.title.localeCompare(b.title,"es"));if(sort==="year")list.sort((a,b)=>b.year-a.year);return list;});
async function search(event:Event){started=performance.now();query=(event.currentTarget as HTMLInputElement).value;await tick();requestAnimationFrame(()=>latency=(performance.now()-started).toFixed(1)+" ms");}
</script>
<svelte:head><title>{selected?selected.title:view==="personal"?"Personal":"Descubrir"} · Prisma muestra</title></svelte:head>
<main class="app">
{#if view==="personal"}
<header class="top"><div><div class="kicker">TU ESPACIO</div><h1>Personal</h1></div><button class="btn" onclick={()=>window.dispatchEvent(new Event("prisma:settings"))}>Ajustes</button></header>
<section class="personal" aria-label="Secciones personales"><a class="tile" href="/?estado=historial"><header><span>↶</span><small>180</small></header><strong>Historial</strong></a><a class="tile" href="/?estado=pendientes"><header><span>▱</span><small>60</small></header><strong>Pendientes</strong></a><a class="tile" href="/"><header><span>◉̸</span><small>12</small></header><strong>Ocultos</strong></a><a class="tile" href="/"><header><span>▂▅▇</span></header><strong>Estadísticas</strong></a></section><a class="manage" href="/"><span>☷</span><strong>Gestionar listas</strong><span>3　›</span></a>
{:else if selected}
<header class="top"><button class="btn" onclick={()=>goto("/")}>← Volver</button><span class="kicker">FICHA DE PRUEBA</span></header><section class="hero" style:--n={selected.seed}><span class="kicker">{selected.genre.toUpperCase()} · {selected.runtime} MIN</span><h1>{selected.title}</h1><p>{selected.year} · {selected.status}</p></section><div class="actions"><button class="btn primary" onclick={()=>ratingDialog.showModal()}>{rating===null?"Calificar":rating+"/10"}</button><button class="btn" onclick={()=>document.getElementById("viewings")?.scrollIntoView({behavior:"smooth"})}>Visionados</button></div><section class="section"><h3>Sinopsis</h3><p>Texto sintético idéntico para la comparación. No se consulta ningún catálogo externo.</p></section><section class="section" id="viewings"><h3>Visionados</h3><p>Dos registros ficticios independientes; no se guardan en almacenamiento.</p></section>
{:else}
<header class="top"><div><div class="kicker">MUESTRA EXPERIMENTAL</div><h1>Descubrir</h1></div><small>Datos ficticios</small></header>
<div class="toolbar" role="search"><label class="sr-only" for="q">Buscar películas por título, género o año</label><input id="q" type="search" placeholder="Buscar películas…" bind:value={query} oninput={search}><button onclick={()=>filter.showModal()}>Filtros</button><button onclick={()=>window.dispatchEvent(new Event("prisma:settings"))}>Ajustes</button></div><div class="results"><span aria-live="polite">{results.length} resultados</span><span>Orden: {sort==="relevance"?"Original":sort==="title"?"Título":"Año"}</span></div>
<div class="feed" aria-label="Feed de películas">{#each results as movie (movie.id)}<a href={"/?pelicula="+movie.id} class="poster" style:--n={movie.seed} aria-label={movie.title+", "+movie.year+", "+movie.genre}><b aria-hidden="true">{movie.title.split(" ").slice(0,2).map(s=>s[0]).join("")}</b><span class="pin">{movie.status}</span></a>{/each}</div><div class="stats">Catálogo sintético: 240 registros · Búsqueda hasta siguiente fotograma: {latency}</div>
{/if}
</main>
<dialog class="dialog" bind:this={filter} aria-labelledby="filter-title"><h2 id="filter-title">Filtros y orden</h2><label>Estado<select bind:value={status}><option value="all">Todas</option><option value="Vista">Vista</option><option value="Pendiente">Pendiente</option></select></label><label>Orden<select bind:value={sort}><option value="relevance">Original</option><option value="title">Título A–Z</option><option value="year">Año reciente</option></select></label><div class="row"><button class="btn" onclick={()=>{status="all";sort="relevance"}}>Restablecer</button><button class="btn primary" onclick={()=>filter.close()}>Aplicar</button></div></dialog>
<dialog class="dialog" bind:this={ratingDialog} aria-labelledby="rating-title"><h2 id="rating-title">Calificar esta película</h2><form onsubmit={e=>{e.preventDefault();const n=Number(new FormData(e.currentTarget as HTMLFormElement).get("rating"));if(n>=1&&n<=10)rating=n;ratingDialog.close()}}><label>Nota<select name="rating" required><option value="">Selecciona</option>{#each Array.from({length:10},(_,i)=>i+1) as n}<option value={n}>{n}/10</option>{/each}</select></label><div class="row"><button class="btn" type="button" onclick={()=>ratingDialog.close()}>Cancelar</button><button class="btn primary" type="submit">Guardar nota</button></div></form></dialog>